/* Markup: <div class="fx-heatmap">THERMAL</div> */

/* Colour tokens — override to re-skin the effect:
   --ink    main text colour (defaults to currentColor)
   --ink-2  primary accent   --ink-3  secondary accent */
:root { --ink: currentColor; --ink-2: #FF4FD8; --ink-3: #4FF8FF; }

/* 49 Heatmap */
.fx-heatmap {
  font: 600 30px/1.1 JetBrains Mono, monospace;
  letter-spacing: .08em;
  color: transparent;
  background: radial-gradient(circle at 20% 50%, #fff26d 0 8%, transparent 24%), radial-gradient(circle at 70% 40%, #ff4f8b 0 12%, transparent 28%), radial-gradient(circle at 44% 78%, var(--ink-3) 0 14%, transparent 32%), linear-gradient(90deg, #2d7dff, #36f0b2, #ffcf4a, #ff4f8b);
  background-size: 130% 130%, 150% 150%, 140% 140%, 260% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  animation: fx-heatmap 3.5s ease-in-out infinite alternate;
}
@keyframes fx-heatmap {
  0% {
    background-position: 0 0, 100% 20%, 40% 100%, 100% 0;
    filter: saturate(1);
  }
  to {
    background-position: 100% 90%, 0 60%, 80% 0, -100% 0;
    filter: saturate(1.35);
  }
}
